import{z as i,x as p,o as s,c as l,q as o,j as d,D as a,d as n,s as t,S as c}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"稀疏集合","description":"","frontmatter":{"title":"稀疏集合","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sparse-set.md","filePath":"cs/sparse-set.md","lastUpdated":1791063341000}'),m={name:"cs/sparse-set.md"};function E(B,e,h,_,D,A){const r=p("Mermaid");return s(),l("div",null,[e[2]||(e[2]=o('<h1 id="稀疏集合" tabindex="-1">稀疏集合 <a class="header-anchor" href="#稀疏集合" aria-label="Permalink to &quot;稀疏集合&quot;">​</a></h1><div class="epigraph"><p>稠密数组记下标，稀疏数组存元素；成员测试是一次下标往返，清集只要把 $n$ 置零。</p><footer>—— 据 Briggs and Torczon, An Efficient Representation for Sparse Sets, ACM Letters on Programming Languages and Systems, 1993；Knuth 整理</footer></div><p><a href="/cs/bitset">上一课</a>在 \\(U\\) 大时要 \\(\\Theta(U/w)\\) 空间与清零。编译器着色、图算法里常有「当前工作集很小、论域下标却到 \\(10^6\\)」。<a href="/cs/array-random-access">数组</a>随机访问仍 \\(O(1)\\)。本课不把位图扫字当默认。缺口是 Briggs–Torczon 稀疏集合：两数组不初始化全体，成员测试仍 \\(O(1)\\)，清空 \\(O(1)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>需要：<code>add</code>/<code>remove</code>/<code>contains</code>、迭代当前 \\(n\\) 个成员、以及反复 <code>clear</code>。位图 <code>clear</code> 是 \\(\\Theta(U/w)\\)；哈希常数大且不保插入序。稀疏集合：<code>dense[0..n)</code> 存元素，\\(`sparse[x]`\\) 若有效则指向 <code>dense</code> 中位置。不变式：</p> \\[x\\in S \\iff 0\\le \\mathrm{sparse}[x]\\lt n \\ \\land\\ \\mathrm{dense}[\\mathrm{sparse}[x]]=x. \\]<p><code>sparse</code> 的垃圾值只要不满足往返就不会被当成成员——因此<strong>不必初始化 <code>sparse</code></strong>。缺口是这个往返测试，不是新的散列。</p><p><span class="marginnote">数字实例：论域 \\(U=10^6\\)、当前集合只有 100 个元素：位图清空要扫约 \\(10^6/64\\approx1.6\\) 万个机器字，稀疏集合把 \\(n\\) 置零，一条指令；迭代成员也只扫 <code>dense[0..100)</code>，与 \\(U\\) 完全无关。</span></p><p><span class="marginnote">Briggs and Torczon 1993 原文用于编译器活跃集。与并查集的「父指针未初始化」同类：用往返或版本号避免 \\(\\Theta(U)\\) 填表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>contains(x)</code>：读 \\(i=\\mathrm{sparse}[x]\\)，判断 \\(i\\lt n\\) 且 <code>dense[i]==x</code>。<code>add</code>：已在则返回；否则 <code>dense[n]=x</code>，<code>sparse[x]=n</code>，\\(n{+}{+}\\)。<code>remove</code>：与末尾交换并改 <code>sparse</code>。<code>clear</code>：\\(n\\leftarrow 0\\)，旧 <code>sparse</code> 槽全部失效。迭代扫 <code>dense[0..n)</code>。</p>',11)),(s(),d(c,null,{default:a(()=>[t(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%80%99%E9%80%89%20x%22%5D%20--%3E%20SP%5B%22i%20%3D%20sparse%5Bx%5D%22%5D%0A%20%20SP%20--%3E%20CK%5B%22i%20%EF%BC%9C%20n%20%E4%B8%94%20dense%5Bi%5D%20%3D%20x%22%5D%0A%20%20CK%20--%3E%20IN%5B%22%E5%9C%A8%E9%9B%86%E5%90%88%E4%B8%AD%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<p>空间仍 \\(\\Theta(U+n)\\) 的数组容量，但清零与迭代按 \\(n\\)。\\(U\\) 必须能分配两个数组；只是不付初始化与按 \\(U\\) 扫描的时间。</p><p><span class="marginnote">直觉类比：<code>sparse[x]</code> 指着一张便签；验证 x 在集合里，就顺着便签去 dense 的那个格子看，里面写的必须还是 x。便签是旧垃圾没关系——只要格子里的名字对不上，这张便签就自动作废，无需打扫。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与位图：精确、无假阳性；交并要按较小集迭代再 contains，不是字级。与哈希：下标即键，无碰撞。版本号变体：<code>sparse</code> 存（位置, 世代），<code>clear</code> 只加世代，可避免交换删除时的部分麻烦，本课点名不写完。</p>',4)),(s(),d(c,null,{default:a(()=>[t(r,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20RM%5B%22remove(x)%22%5D%20--%3E%20I%5B%22%E5%AE%9A%E4%BD%8D%20i%20%3D%20sparse%5Bx%5D%22%5D%0A%20%20I%20--%3E%20LAST%5B%22%E5%8F%96%20dense%20%E6%9C%AB%E5%B0%BE%E5%85%83%E7%B4%A0%20y%22%5D%0A%20%20LAST%20--%3E%20SW%5B%22dense%5Bi%5D%20%3D%20y%20%E4%B8%94%20sparse%5By%5D%20%3D%20i%22%5D%0A%20%20SW%20--%3E%20DEC%5B%22n%20%E5%87%8F%E4%B8%80%22%5D%0A%20%20DEC%20--%3E%20INV%5B%22%E5%BE%80%E8%BF%94%E4%B8%8D%E5%8F%98%E5%BC%8F%E4%BB%8D%E6%88%90%E7%AB%8B%22%5D%0A%20%20CL%5B%22clear%22%5D%20--%3E%20Z%5B%22n%20%3D%200%EF%BC%8C%E6%97%A7%20sparse%20%E6%A7%BD%E5%85%A8%E9%83%A8%E5%A4%B1%E6%95%88%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<p>这张图回答的是：删除与清空如何在不打扫 <code>sparse</code> 的前提下维持不变式——交换删除只改 <code>dense[i]</code> 与 <code>sparse[y]</code> 两处，<code>clear</code> 干脆让全部旧槽因 \\(n=0\\) 失效。</p><p>区间查询课序在此收束：序列上从可逆前缀、幂等倍增、可更新树、扫描单调、分块离线，收到位级与稀疏下标。下一单元回到有序字典与堆的对数结构，不重写<a href="/cs/rbtree-intuition">红黑直觉</a> 的着色 case。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>键必须是 \\([0,U)\\) 整数。字符串键先编号。并发无锁稀疏集不是本课。不要把未初始化 <code>sparse</code> 读进未定义行为——语言合同须保证读任意位型合法（或先用 mmap 等零页）。</p><p><span class="marginnote">常见误区：初学者容易以为「不初始化 <code>sparse</code>」是 bug。恰恰相反：任何垃圾值都过不了往返验证，所以初始化 \\(\\Theta(U)\\) 的时间根本不用付——这正是它对比位图、对比 memset 清零最大的优势。</span></p><p>后课默认：小工作集、大下标论域，用稀疏集合。平衡树与随机 BST 的续篇从 Treap 开始。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>稀疏集合：dense/sparse 往返，\\(O(1)\\) 成员与清空。</li><li>不初始化 sparse；迭代按 \\(n\\)。</li><li>序列区间课序结束；下一课 Treap 接对数字典。</li><li>出处：Briggs and Torczon, <em>LOPLAS</em>, 1993。</li></ul>',8))])}const x=i(m,[["render",E]]);export{f as __pageData,x as default};
